import { useEffect, useState } from 'react';
import { subscribeVoiceStatus, type VoiceStatus } from '../services/supertonicTts';

export function VoiceDownloadStatus() {
  const [status, setStatus] = useState<VoiceStatus>({ phase: 'idle', message: '' });
  useEffect(() => subscribeVoiceStatus(setStatus), []);
  return <VoiceProgress status={status} />;
}

export function VoiceProgress({ status }: { status: VoiceStatus }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (!['loading', 'preparing', 'synthesizing'].includes(status.phase)) return;
    const timer = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(timer);
  }, [status.phase]);
  if (!['loading', 'preparing', 'synthesizing', 'error'].includes(status.phase)) return null;
  if (!import.meta.env.DEV && status.phase === 'synthesizing') return null;
  const hasByteProgress = ['loading', 'preparing'].includes(status.phase) && !!status.totalBytes;
  const format = (bytes: number) => (bytes / 1000000).toFixed(1);
  return (
    <div className="fixed bottom-0 inset-x-0 z-[100] bg-[#180f26]/95 border-t border-[#d4af37]/30 text-[#e6d8be] font-mono text-[10px]"
      style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
      <div className="flex items-center justify-between gap-3 px-3 py-1">
        {status.phase !== 'error' && <span key={status.confirmedAt} aria-hidden="true" className="voice-measurement-ack h-2 w-2 rounded-full bg-[#d4af37] shrink-0" />}
        <span role="status">{import.meta.env.DEV || status.phase === 'error' ? status.message : hasByteProgress ? 'Downloading Natally’s voice for this device…' : 'Preparing Natally’s voice…'}</span>
        {hasByteProgress && <span className="shrink-0 tabular-nums">
          {format(status.loadedBytes || 0)} / {format(status.totalBytes!)} MB
        </span>}
      </div>
      {import.meta.env.DEV && status.phase !== 'error' && status.startedAt && <div className="px-3 pb-1 tabular-nums">
        {(Math.max(0, now - status.startedAt) / 1000).toFixed(1)}s elapsed · last work measurement {(Math.max(0, now - (status.confirmedAt || status.startedAt)) / 1000).toFixed(1)}s ago
        {status.heartbeatAt && <> · <span key={status.heartbeatAt} className="voice-measurement-ack inline-block">worker responded</span> {(Math.max(0, now - status.heartbeatAt) / 1000).toFixed(1)}s ago</>}
      </div>}
      {import.meta.env.DEV && (status.files || status.graphs) && <details className="px-3 pb-1 max-h-[40vh] overflow-auto">
        <summary className="cursor-pointer">Actual files and ONNX graphs{status.file ? ` · ${status.file}` : ''}</summary>
        {status.files?.map(file => <div key={file.file} className="py-1">
          <div className="flex justify-between gap-2"><span>{file.file} · {file.source === 'cache' ? 'saved cache' : file.source === 'network' ? 'network response' : 'source not yet measured'}</span><span>{format(file.loadedBytes)} / {format(file.totalBytes)} MB</span></div>
          <progress aria-label={file.file + ' bytes read'} max={file.totalBytes} value={file.loadedBytes} className="block w-full h-1 accent-[#d4af37]" />
        </div>)}
        {status.graphs?.map(graph => <div key={graph.operation + graph.file + graph.backend} className="py-1">
          <span>{graph.file} · {graph.backend} · {graph.operation === 'session' ? 'initialization' : 'execution'} · {graph.completed}{graph.expected ? '/' + graph.expected : ''} completed{graph.state === 'start' ? ' · waiting for runtime completion' : graph.state === 'error' ? ' · failed' : ''}{graph.durationMs !== undefined ? ` · last operation ${(graph.durationMs / 1000).toFixed(3)}s` : ''}</span>
          {graph.expected && <progress aria-label={graph.file + ' ' + graph.operation + ' completions'} max={graph.expected} value={graph.completed} className="block w-full h-1 accent-[#d4af37]" />}
        </div>)}
      </details>}
      {['loading', 'preparing'].includes(status.phase) && <progress aria-label={hasByteProgress ? 'Voice model bytes loaded' : 'Preparing local voice runtime'}
        max={hasByteProgress ? status.totalBytes : undefined}
        value={hasByteProgress ? status.loadedBytes || 0 : undefined}
        className="block w-full h-[2px] accent-[#d4af37]" />}
    </div>
  );
}

// Natally's voice for the app surface: one engine, the original's.
// The original voiceService (F4 speaker, pitch 1.15, soft tone, kawaii
// preset) synthesizes and plays every utterance, and emits the real
// per-word `natally-voice-performance` events — timed from the actual audio
// duration — that drive the verbatim AtelierCharacter's mouth. This module
// only adapts that engine to the streaming `Voice` interface the app uses
// (token fragments in, sentences out, gesture-gated admission) and mirrors
// word boundaries into `natally-karaoke` caption events.

import { initSupertonic, subscribeVoiceStatus } from '../atelier-original/services/supertonicTts';
import {
 getSharedAudioContext,
 loadVoiceSettings,
 speakNatallyText,
 stopSpeaking,
} from '../atelier-original/services/voiceService';

export interface SpeakOptions {
 /**
  * End-of-utterance marker: also speak buffered text that lacks closing
  * punctuation. The next speakStream call after a flush starts a new
  * utterance and supersedes anything still audible.
  */
 flush?: boolean;
}

export interface VoiceState {
 /** Whether a user gesture has admitted audio (`admit()`). */
 admitted: boolean;
 /** True while sentences are queued, synthesizing, or audible. */
 speaking: boolean;
 /** Last truthful engine failure, or null. */
 error: string | null;
}

/** Word-by-word caption progress for the karaoke line. */
export interface KaraokeDetail {
 line: string;
 wordIndex: number;
 wordCount: number;
}

export interface Voice {
 /**
  * Feed answer text; fragments are fine. Complete sentences are spoken in
  * order; `{ flush: true }` speaks the remainder. One utterance at a time:
  * the first call after a flush/stop cancels whatever is still audible.
  */
 speakStream(text: string, opts?: SpeakOptions): void;
 /** Stop queued and playing speech immediately; drop buffered text. */
 stop(): void;
 /** Admit audio; call inside a real click/key handler. */
 admit(): void;
 /** Whether audio has been admitted by a user gesture. */
 readonly admitted: boolean;
 /** Subscribe to state changes (invoked immediately). Returns unsubscribe. */
 onState(cb: (state: VoiceState) => void): () => void;
}

/** Longest prefix ending at a sentence boundary, or '' while none yet. */
const COMPLETE_SENTENCES = /^[\s\S]*[.!?…][”’"')\]]*(?=\s|$)/;

function dispatchKaraoke(detail: KaraokeDetail): void {
 window.dispatchEvent(new CustomEvent<KaraokeDetail>('natally-karaoke', { detail }));
}

export function createVoice(): Voice {
 const listeners = new Set<(state: VoiceState) => void>();
 const state: VoiceState = { admitted: false, speaking: false, error: null };
 const emit = () => {
  const snapshot = { ...state };
  for (const listener of listeners) listener(snapshot);
 };

 let pending = '';
 let queue: string[] = [];
 let fresh = true;
 let epoch = 0;
 let running = false;

 subscribeVoiceStatus(status => {
  const error = status.phase === 'error' ? status.message ?? 'Voice failed.' : null;
  if (error !== state.error) {
   state.error = error;
   emit();
  }
 });

 const pump = async () => {
  if (running || !state.admitted || queue.length === 0) return;
  running = true;
  const mine = epoch;
  state.speaking = true;
  emit();
  try {
   while (queue.length > 0 && mine === epoch) {
    const line = queue.shift()!;
    const words = [...line.matchAll(/\S+/g)];
    await speakNatallyText(line, loadVoiceSettings(), undefined, undefined, (charIndex: number) => {
     const wordIndex = Math.max(0, words.findIndex(word => word.index! >= charIndex));
     dispatchKaraoke({ line, wordIndex, wordCount: words.length });
    });
   }
  } finally {
   running = false;
   if (queue.length > 0) void pump();
   else if (mine === epoch) {
    state.speaking = false;
    emit();
   }
  }
 };

 const stop = () => {
  epoch += 1;
  queue = [];
  pending = '';
  fresh = true;
  stopSpeaking();
  if (state.speaking) {
   state.speaking = false;
   emit();
  }
 };

 return {
  speakStream(text, opts) {
   if (fresh) {
    stop();
    fresh = false;
   }
   pending += text;
   const complete = opts?.flush ? pending : (COMPLETE_SENTENCES.exec(pending)?.[0] ?? '');
   pending = pending.slice(complete.length);
   if (complete.trim() !== '') queue.push(complete.trim());
   if (opts?.flush) fresh = true;
   void pump();
  },
  stop,
  admit() {
   if (state.admitted) return;
   state.admitted = true;
   // Resume inside the gesture: browsers only unlock audio here.
   void getSharedAudioContext()?.resume();
   void initSupertonic().catch(() => { });
   emit();
   void pump();
  },
  get admitted() {
   return state.admitted;
  },
  onState(cb) {
   listeners.add(cb);
   cb({ ...state });
   return () => listeners.delete(cb);
  },
 };
}

