1	// Interactive three.js natal-chart renderer. Scene construction, disposal,
2	// and picking live in ./scene (pure three.js); this component owns the canvas
3	// element, pointer/wheel input, resize observation, and the render loop.
4	
5	import { useEffect, useRef } from 'react';
6	import type { ChartBodyKey, NatalChart } from '../shared/types';
7	import { createChartScene } from './scene';
8	import type { ChartScene } from './scene';
9	
10	export interface AstroChartProps {
11	  chart: NatalChart;
12	  /** Fires with the hovered body's key, or null when nothing is hovered. */
13	  onHoverBody?: (key: ChartBodyKey | null) => void;
14	  /**
15	   * Guided-reading focus: this body stays lit while its siblings dim (the
16	   * wheel itself never dims). null/undefined restores all bodies.
17	   */
18	  readonly activeBody?: ChartBodyKey | null;
19	}
20	
21	export function AstroChart({ chart, onHoverBody, activeBody = null }: AstroChartProps) {
22	  const hostRef = useRef<HTMLDivElement | null>(null);
23	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
24	  const hoverCallbackRef = useRef<AstroChartProps['onHoverBody']>(undefined);
25	  const sceneRef = useRef<ChartScene | null>(null);
26	  const activeBodyRef = useRef<AstroChartProps['activeBody']>(activeBody);
27	
28	  useEffect(() => {
29	    hoverCallbackRef.current = onHoverBody;
30	  }, [onHoverBody]);
31	
32	  useEffect(() => {
33	    activeBodyRef.current = activeBody;
34	    sceneRef.current?.setActiveBody(activeBody);
35	  }, [activeBody]);
36	
37	  useEffect(() => {
38	    const host = hostRef.current;
39	    const canvas = canvasRef.current;
40	    if (!host || !canvas) return;
41	
42	    let scene: ChartScene;
43	    try {
44	      scene = createChartScene(canvas, chart);
45	    } catch {
46	      // WebGL unavailable: leave the canvas blank rather than crash the app.
47	      return;
48	    }
49	    sceneRef.current = scene;
50	    scene.setActiveBody(activeBodyRef.current ?? null);
51	
52	    scene.resize(host.clientWidth, host.clientHeight);
53	    const resizeObserver = new ResizeObserver(entries => {
54	      const box = entries[entries.length - 1]?.contentRect;
55	      if (box) scene.resize(box.width, box.height);
56	    });
57	    resizeObserver.observe(host);
58	
59	    let frame = 0;
60	    let lastFrameAt = performance.now();
61	    const tick = (now: number) => {
62	      const delta = Math.min(Math.max((now - lastFrameAt) / 1000, 0), 0.05);
63	      lastFrameAt = now;
64	      scene.update(delta);
65	      frame = requestAnimationFrame(tick);
66	    };
67	    frame = requestAnimationFrame(tick);
68	
69	    // Redraw canvas text once Playfair Display has actually loaded.
70	    let labelsWanted = true;
71	    document.fonts.ready
72	      .then(() => {
73	        if (labelsWanted) scene.refreshLabels();
74	      })
75	      .catch(() => undefined);
76	
77	    let hovered: ChartBodyKey | null = null;
78	    const setHovered = (key: ChartBodyKey | null) => {
79	      if (hovered === key) return;
80	      hovered = key;
81	      scene.setHover(key);
82	      canvas.style.cursor = key ? 'pointer' : 'grab';
83	      hoverCallbackRef.current?.(key);
84	    };
85	
86	    let dragging = false;
87	    let dragPointerId = -1;
88	    let lastX = 0;
89	    let lastY = 0;
90	
91	    const onPointerDown = (event: PointerEvent) => {
92	      dragging = true;
93	      dragPointerId = event.pointerId;
94	      lastX = event.clientX;
95	      lastY = event.clientY;
96	      try {
97	        canvas.setPointerCapture(event.pointerId);
98	      } catch {
99	        // Pointer already gone; drag simply ends early.
100	      }
101	      canvas.style.cursor = 'grabbing';
102	    };
103	
104	    const onPointerMove = (event: PointerEvent) => {
105	      if (dragging) {
106	        if (event.pointerId !== dragPointerId) return;
107	        scene.spinBy(event.clientX - lastX, event.clientY - lastY);
108	        lastX = event.clientX;
109	        lastY = event.clientY;
110	        return;
111	      }
112	      const rect = canvas.getBoundingClientRect();
113	      if (rect.width === 0 || rect.height === 0) return;
114	      const ndcX = ((event.clientX - rect.left) / rect.width) * 2 - 1;
115	      const ndcY = -(((event.clientY - rect.top) / rect.height) * 2 - 1);
116	      setHovered(scene.pickAt(ndcX, ndcY));
117	    };
118	
119	    const onPointerUp = (event: PointerEvent) => {
120	      if (event.pointerId !== dragPointerId) return;
121	      dragging = false;
122	      dragPointerId = -1;
123	      if (canvas.hasPointerCapture(event.pointerId)) {
124	        try {
125	          canvas.releasePointerCapture(event.pointerId);
126	        } catch {
127	          // Already released.
128	        }
129	      }
130	      canvas.style.cursor = hovered ? 'pointer' : 'grab';
131	    };
132	
133	    const onPointerLeave = () => {
134	      setHovered(null);
135	    };
136	
137	    const onWheel = (event: WheelEvent) => {
138	      event.preventDefault();
139	      scene.zoomBy(event.deltaY);
140	    };
141	
142	    canvas.addEventListener('pointerdown', onPointerDown);
143	    canvas.addEventListener('pointermove', onPointerMove);
144	    canvas.addEventListener('pointerup', onPointerUp);
145	    canvas.addEventListener('pointercancel', onPointerUp);
146	    canvas.addEventListener('pointerleave', onPointerLeave);
147	    canvas.addEventListener('wheel', onWheel, { passive: false });
148	
149	    return () => {
150	      sceneRef.current = null;
151	      labelsWanted = false;
152	      cancelAnimationFrame(frame);
153	      resizeObserver.disconnect();
154	      canvas.removeEventListener('pointerdown', onPointerDown);
155	      canvas.removeEventListener('pointermove', onPointerMove);
156	      canvas.removeEventListener('pointerup', onPointerUp);
157	      canvas.removeEventListener('pointercancel', onPointerUp);
