(async () => {
  const canvas = document.querySelector('canvas');
  const rect = canvas.getBoundingClientRect();
  const out = { rect: { l: rect.left, t: rect.top, w: rect.width, h: rect.height } };
  const move = (x, y) => canvas.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y }));
  let hit = null;
  for (let fy = 0.1; fy <= 0.9 && !hit; fy += 0.03) {
    for (let fx = 0.1; fx <= 0.9 && !hit; fx += 0.03) {
      const x = rect.left + rect.width * fx, y = rect.top + rect.height * fy;
      move(x, y);
      await new Promise(r => requestAnimationFrame(r));
      if (canvas.style.cursor && canvas.style.cursor !== 'default') { hit = { x, y }; out.hoverCursor = canvas.style.cursor; }
    }
  }
  if (!hit) return { ...out, error: 'no hover' };
  out.hit = { x: Math.round(hit.x), y: Math.round(hit.y) };
  out.underAtHit = document.elementFromPoint(hit.x, hit.y)?.outerHTML?.slice(0, 80);
  // Re-hover at the hit point first (mousedown dismisses hover, click re-picks)
  move(hit.x, hit.y);
  await new Promise(r => setTimeout(r, 150));
  const opts = { bubbles: true, cancelable: true, composed: true, clientX: hit.x, clientY: hit.y, button: 0, buttons: 1, detail: 1 };
  canvas.dispatchEvent(new MouseEvent('mousedown', opts));
  await new Promise(r => setTimeout(r, 50));
  canvas.dispatchEvent(new MouseEvent('mouseup', { ...opts, buttons: 0 }));
  canvas.dispatchEvent(new MouseEvent('click', { ...opts, buttons: 0, detail: 1 }));
  await new Promise(r => setTimeout(r, 800));
  out.cursorAfter = canvas.style.cursor;
  return out;
})()

