(async () => {
  // Install observers first
  window.__cold = { log: [], bar: [] };
  for (const name of ['natally-voice-performance', 'natally-karaoke']) {
    window.addEventListener(name, e => {
      const d = e.detail || {};
      window.__cold.log.push({ t: Math.round(performance.now()), ev: name.includes('karaoke') ? 'k' : 'p', s: d.state ?? null, w: d.text ?? null });
    });
  }
  // Wait for the chart canvas and a hoverable body, then tap — while the model downloads.
  const deadline = performance.now() + 60000;
  let canvas = null, hit = null;
  while (performance.now() < deadline && !hit) {
    canvas = document.querySelector('canvas');
    if (canvas) {
      const rect = canvas.getBoundingClientRect();
      if (rect.width > 50) {
        for (let fy = 0.08; fy <= 0.92 && !hit; fy += 0.03) {
          for (let fx = 0.08; fx <= 0.92 && !hit; fx += 0.03) {
            const x = rect.left + rect.width * fx, y = rect.top + rect.height * fy;
            canvas.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y }));
            await new Promise(r => requestAnimationFrame(r));
            if (canvas.style.cursor === 'pointer' || canvas.style.cursor === 'help') hit = { x, y, cursor: canvas.style.cursor };
          }
        }
      }
    }
    if (!hit) await new Promise(r => setTimeout(r, 500));
  }
  if (!hit) return { error: 'no hover target in 60s' };
  const barAtTap = [...document.querySelectorAll('[role="status"]')].map(e => e.textContent).find(t => t && /MB|%|voice/i.test(t))?.slice(0, 90) ?? null;
  window.__cold.tapAt = Math.round(performance.now());
  window.__cold.barAtTap = barAtTap;
  const opts = { bubbles: true, cancelable: true, composed: true, clientX: hit.x, clientY: hit.y, button: 0, buttons: 1, detail: 1 };
  canvas.dispatchEvent(new MouseEvent('mousedown', opts));
  await new Promise(r => setTimeout(r, 50));
  canvas.dispatchEvent(new MouseEvent('mouseup', { ...opts, buttons: 0 }));
  canvas.dispatchEvent(new MouseEvent('click', { ...opts, buttons: 0, detail: 1 }));
  return { tapped: true, hit: { x: Math.round(hit.x), y: Math.round(hit.y), cursor: hit.cursor }, barAtTap };
})()

